// Service worker: makes the app work offline and delivers new versions.
// The block between the markers is regenerated by `npm run build`
// (Vercel runs it on every deploy), so each deploy gets a new cache.

// <precache>
const VERSION = '08ef55e765a9';
const PRECACHE = [
  '/',
  '/css/app.css',
  '/icons/apple-touch-icon.png',
  '/icons/favicon-32.png',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/icon.svg',
  '/icons/maskable-512.png',
  '/js/app.js',
  '/js/data/basics.js',
  '/js/data/defaults.js',
  '/js/dates.js',
  '/js/engine.js',
  '/js/learn.js',
  '/js/parse.js',
  '/js/planner.js',
  '/js/problems.js',
  '/js/store.js',
  '/js/ui.js',
  '/js/views/common.js',
  '/js/views/plan.js',
  '/js/views/schedule.js',
  '/js/views/settings.js',
  '/js/views/tasks.js',
  '/js/views/today.js',
  '/js/views/track.js',
  '/js/xlsx.js',
  '/manifest.webmanifest'
];
// </precache>

const CACHE = `roadmap-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
});

// A new version waits until the page asks it to take over ("Update" button).
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('roadmap-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // The app is a single page: every navigation gets the cached shell.
  if (req.mode === 'navigate') {
    event.respondWith(caches.match('/').then((cached) => cached || fetch(req)));
    return;
  }

  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(
      (cached) =>
        cached ||
        fetch(req).then((res) => {
          if (res.ok && res.type === 'basic') {
            const copy = res.clone();
            caches.open(CACHE).then((cache) => cache.put(req, copy));
          }
          return res;
        }),
    ),
  );
});
